"""Writes docs/julie-questions.md from the claims register, the fact register and LAUNCH-CHECKLIST.md – always current."""
import os, json, re, datetime
ROOT = r"C:\Users\belko\AGI"; B = os.path.join(ROOT, "v2", "_build")
claims = json.load(open(os.path.join(B, "claims.json"), encoding="utf-8"))
facts = json.load(open(os.path.join(B, "facts.json"), encoding="utf-8"))
out = [f"# Questions for Julie – generated {datetime.date.today():%B %d, %Y}", "",
       "Generated by `v2/_build/julie_questions.py` from the claims register, the fact register and the launch checklist. "
       "Answers go back into `v2/_build/facts.json`, `v2/_build/claims.json` and `v2/LAUNCH-CHECKLIST.md`.", "",
       "## 1. Claims to confirm or correct", ""]
for c in claims:
    if c["status"] in ("open",):
        out.append(f"- **[{c['id']}] {c['claim']}** – source: {c['source']} – needed: {c['decision']}")
out += ["", "## 2. Facts to confirm", ""]
for group, items in facts.items():
    for key, f in items.items():
        if f.get("status") == "to-confirm":
            v = f.get("value"); v = "—" if v in (None, "") else (", ".join(v) if isinstance(v, list) else (json.dumps(v, ensure_ascii=False) if isinstance(v, dict) else str(v)))
            if len(v) > 160: v = v[:160] + "…"
            out.append(f"- **{group} › {key}**: {v}" + (f" — {f['note']}" if f.get("note") else ""))
chk = open(os.path.join(ROOT, "v2", "LAUNCH-CHECKLIST.md"), encoding="utf-8").read().split("\n")
sec = ""; open_items = []
for l in chk:
    if l.startswith("## "): sec = l[3:].strip()
    elif l.strip().startswith("- [ ]"): open_items.append((sec, l.strip()[6:]))
out += ["", f"## 3. Open checklist items ({len(open_items)})", ""]
last = None
for sec, item in open_items:
    if sec != last: out += ["", f"**{sec}**"]; last = sec
    out.append(f"- {item}")
out += ["", "## 4. Material to send", "", "- Photos for every `Photo` slot on the site (see the preview) – only students with photo consent",
        "- 3–6 real testimonials with written permission (`docs/parent-stories-guide.md`)", "- 2026–27 Saturday class schedule", "- Current team list with roles and photos", "- Someone qualified to review Privacy, Terms, Cookies and the consent forms"]
open(os.path.join(ROOT, "docs", "julie-questions.md"), "w", encoding="utf-8").write("\n".join(out) + "\n")
print(f"docs/julie-questions.md: {sum(1 for c in claims if c['status']=='open')} claims, {sum(1 for g in facts.values() for f in g.values() if f.get('status')=='to-confirm')} facts, {len(open_items)} checklist items")
